const session = client.startSession();
try {
await session.withTransaction(async () => {
await db.collection('orders').insertOne(order, { session });
await db.collection('outbox').insertOne({
aggregate: 'order',
aggregate_id: order._id,
event_type: 'order.created',
payload: { order_id: order._id, user_id: order.user_id, total: order.total },
version: 1,
occurred_at: new Date(),
published_at: null,
attempts: 0,
}, { session });
});
} finally {
await session.endSession();
}
Both writes commit together or neither does. The business state and the to-be-published event are forever consistent.

const cs = db.collection('outbox').watch(
[{ $match: { operationType: 'insert' } }],
{ fullDocument: 'updateLookup' }
);
let lastToken = await loadResumeToken();
const stream = lastToken ? db.collection('outbox').watch([], { resumeAfter: lastToken }) : cs;
for await (const change of stream) {
const event = change.fullDocument;
try {
await kafka.send({ topic: event.event_type, key: event.aggregate_id, value: JSON.stringify(event) });
await db.collection('outbox').updateOne({ _id: event._id }, { $set: { published_at: new Date() } });
await persistResumeToken(change._id);
} catch (err) {
// log + back off; do NOT persist the token until success → consumer will re-receive on restart
await db.collection('outbox').updateOne({ _id: event._id }, { $inc: { attempts: 1 } });
await sleep(backoff(event.attempts));
}
}
Properties:
At-least-once delivery — on crash before token persist, we replay.
Resume token persisted after successful publish + mark.
Network blip → retried with backoff, attempts incremented.
This pattern needs no external infrastructure beyond your existing MongoDB. The publisher can run anywhere — a sidecar, a long-running container, a dedicated tiny pod.

If change streams aren't available (standalone Mongo, very old versions, or a multi-region setup with restricted secondary access):
async function publishLoop() {
while (true) {
const events = await db.collection('outbox')
.find({ published_at: null })
.sort({ occurred_at: 1 })
.limit(100)
.toArray();
if (!events.length) { await sleep(1000); continue; }
for (const ev of events) {
try {
await kafka.send({ topic: ev.event_type, key: ev.aggregate_id, value: JSON.stringify(ev) });
await db.collection('outbox').updateOne({ _id: ev._id }, { $set: { published_at: new Date() } });
} catch {
await db.collection('outbox').updateOne({ _id: ev._id }, { $inc: { attempts: 1 } });
}
}
}
}
Higher latency (poll interval) + more DB queries; rock-solid. Use change streams when available, polling as fallback.

Every outbox event has a unique _id. Consumers track processed IDs (in a "consumed_events" collection, Redis set, etc.). Skip if already processed.
const r = await db.collection('consumed_events').updateOne(
{ _id: event._id },
{ $setOnInsert: { processed_at: new Date() } },
{ upsert: true }
);
if (r.upsertedCount === 0) return; // already processed; skip
await applyEvent(event);

Kafka topics + partitions preserve order within a partition. Choose your partition key to match the ordering you need.
await kafka.send({
topic: event.event_type,
key: event.aggregate_id, // events for the same order land on same partition → ordered
value: ...
});
For "all events on this order, in order" → key on aggregate_id.
For "every event in occurrence order globally" → single-partition topic (low throughput).
Most outbox usage cares about per-aggregate ordering — keying by aggregate_id is the right default.

When the downstream is down for hours:
Outbox grows. Disk usage climbs.
If you have TTL on published_at: null, you'll lose unpublished events — don't TTL the unpublished portion.
The publisher must implement exponential backoff to avoid hammering a downed downstream.
Dead Letter Queue pattern:
if (event.attempts > 10) {
await db.collection('outbox_dlq').insertOne({ ...event, dlq_at: new Date() });
await db.collection('outbox').deleteOne({ _id: event._id });
alert("outbox event moved to DLQ", event);
}
Alert + investigate. Don't silently drop.
